const matches = raw.match(/\{[\s\S]*?\}/g);

if (!matches || matches.length === 0) {
  throw new Error("No JSON found");
}

// Take the LAST match (usually the real output)
const jsonString = matches[matches.length - 1];

return [
  {
    json: JSON.parse(jsonString)
  }
];

