const raw = $json.output || "";

// Find the final JSON object
const start = raw.lastIndexOf('{');

if (start === -1) {
  throw new Error("No JSON found");
}

// Extract JSON only
const jsonString = raw.slice(start);

// Parse and return clean structured object
const parsed = JSON.parse(jsonString);

return [
  {
    json: parsed
  }
];

const activeProduct =
  $input.first().json.active_product || null;

return [
  {
    json: {
      active_product: activeProduct
    }
  }
];

const current = $json;

// safely read previous state
const previousActiveProduct =
  current.active_product || null;

// current detected product
const detectedProduct =
  current.product_query || null;

// update active product only if new one exists
const activeProduct =
  detectedProduct || previousActiveProduct;

// final output
return [
  {
    json: {
      ...current,
      active_product: activeProduct
    }
  }
];
